SELECT EXISTS(
    SELECT 1 FROM images g LEFT JOIN items i ON i.id=g.item_id
    WHERE g.id=#{id} AND (
        (g.item_id IS NULL AND g.uploader_id=#{userId})
        OR (g.item_id IS NOT NULL AND (
            i.status='PUBLISHED' OR i.publisher_id=#{userId} OR #{admin}
            OR EXISTS(SELECT 1 FROM claims c WHERE c.item_id=i.id AND c.applicant_id=#{userId})
            OR EXISTS(SELECT 1 FROM clues c WHERE c.lost_item_id=i.id AND c.provider_id=#{userId})
        ))
    )
)

SELECT  FROM images WHERE item_id IN
#{id}
ORDER BY item_id, position
